        "benefits": [
          {
            "number": 1,
            "titleZh": "描述水如何把人或物沖走",
            "titleEn": "Describe how water moves people and things",
            "zh": "wash away 和 wash out 可以表示水把某人或某物從一個地方沖到另一個地方。",
            "en": "Wash away and wash out can show water carrying something from one place to another.",
            "sourcePage": 2
          },
          {
            "number": 2,
            "titleZh": "按不同清潔情況選用準確表達",
            "titleEn": "Choose the right expression for different kinds of cleaning",
            "zh": "清洗較大的表面可用 wash down；洗掉表面痕跡可用 wash off；洗掉布料中的污漬或清洗容器內部可用 wash out。",
            "en": "Use wash down for a large surface, wash off for a mark on a surface, and wash out for a stain in cloth or the inside of a container.",
            "sourcePage": 2
          },
          {
            "number": 3,
            "titleZh": "自然談論飯後的日常家務",
            "titleEn": "Talk naturally about an everyday job after meals",
            "zh": "在英式英語中，wash up 是表示清洗碟子、杯子和平底鍋的常用說法。",
            "en": "In British English, wash up is a common way to talk about cleaning plates, cups and pans.",
            "sourcePage": 2
          },
          {
            "number": 4,
            "titleZh": "形容某人累得筋疲力盡",
            "titleEn": "Describe being completely tired",
            "zh": "wash somebody out 可以自然有力地表示某項活動令某人非常疲倦。",
            "en": "Wash somebody out gives a strong, natural way to say that an activity has made someone extremely tired.",
            "sourcePage": 3
          }
        ],
