        "benefits": [
          {
            "titleZh": "描述輕微接觸和近距離移動",
            "titleEn": "Describe light contact and close movement",
            "zh": "brush against、brush by 和 brush past 可以描述人、動物或物件經過時非常接近另一物件,甚至輕輕碰到它。",
            "en": "Brush against, brush by and brush past help you describe a person, animal or object moving very close to something and touching it lightly."
          },
          {
            "titleZh": "清楚談論清潔動作",
            "titleEn": "Talk clearly about cleaning",
            "zh": "BRUSH 片語動詞可以幫助你描述刷走泥、灰塵、沙、碎屑和鬆散頭髮等不同清潔動作。",
            "en": "The BRUSH family gives you several useful ways to talk about removing mud, dust, sand, crumbs and loose hair."
          },
          {
            "titleZh": "描述別人如何受到對待",
            "titleEn": "Describe how someone is treated",
            "zh": "brush somebody off 可以表示某人不獲理會,或在對方沒有認真聆聽的情況下被打發走。",
            "en": "Brush somebody off shows that a person is being ignored or dismissed without enough attention."
          },
          {
            "titleZh": "談論重溫已有技能",
            "titleEn": "Talk about improving old skills",
            "zh": "brush up 和 brush up on 可以表示重溫一段時間沒有使用的知識或技能。",
            "en": "Brush up and brush up on help you explain that you are reviewing knowledge or skills that you have not used recently."
          }
        ],
